/-- For [the supplied quantities and conditions](hyp:m,n), the [adaptive pilot size](goal) is the mathematical object specified below. -/
def adaptivePilotSize (m : ℕ → ℕ) (n : ℕ) : ℕ :=
  min (m n) n

/-- For the supplied quantities and conditions, the adaptive true param is the mathematical object specified below. [The adaptive True Param](goal) is determined by [the displayed parameters](hyp:θ,h,n). -/
def adaptiveTrueParam (θ h : TrialParameter) (n : ℕ) : TrialParameter :=
  if InteriorMeans (localAlternative θ h n) then localAlternative θ h n else θ

/-- The paper's staircase increment is evaluated only at a positive privacy budget. For the displayed inputs and conditions, the stated result follows. For the displayed quantities and conditions, these specify the stated inputs. [The admissible Privacy Increment](goal) is determined by [the displayed parameters](hyp:ε,_hε). -/
def admissiblePrivacyIncrement (ε : ℝ) (_hε : 0 < ε) : ℝ :=
  privacyIncrement ε -- @realizes d(exp ε - 1 with ε>0)

/-- The paper's likelihood-ratio parameter is evaluated only at a positive privacy budget. For the displayed inputs and conditions, the stated result follows. For the displayed quantities and conditions, these specify the stated inputs. [The admissible Privacy Ratio](goal) is determined by [the displayed parameters](hyp:ε,_hε). -/
def admissiblePrivacyRatio (ε : ℝ) (_hε : 0 < ε) : ℝ :=
  privacyRatio ε -- @realizes r(exp ε with ε>0)

/-- For [the supplied quantities and conditions](hyp:variance,n), the [asymptotic wald half length](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:γ), these specify the stated inputs. -/
def asymptoticWaldHalfLength (γ variance : ℝ) (n : ℕ) : ℝ :=
  waldCriticalValue γ * Real.sqrt (variance / n)

/-- For [the supplied quantities and conditions](hyp:p), the [centered r5 direction](goal) is the mathematical object specified below. -/
def centeredR5Direction (p : ℝ) : ℝ :=
  (p - centeredR5Scale p) / centeredR5Denom p

/-- For [the supplied quantities and conditions](hyp:p), the [centered r5 left score](goal) is the mathematical object specified below. -/
def centeredR5LeftScore (p : ℝ) : ℝ :=
  p - (1 - 2 * p) * centeredR5Direction p

/-- For [the supplied quantities and conditions](hyp:p), the [centered r5 right score](goal) is the mathematical object specified below. -/
def centeredR5RightScore (p : ℝ) : ℝ :=
  2 * p * (centeredR5Direction p + 1) / (1 + p)

/-- For [the supplied quantities and conditions](hyp:p), the [centered r5 scale](goal) is the mathematical object specified below. -/
def centeredR5Scale (p : ℝ) : ℝ :=
  Real.sqrt (8 * p ^ 2 / (5 * (1 + p)))

/-- For [the supplied quantities and conditions](hyp:p), the [centered r5 value](goal) is the mathematical object specified below. -/
def centeredR5Value (p : ℝ) : ℝ :=
  centeredR5Scale p ^ 2 * (1 - p) ^ 2 / centeredR5Denom p ^ 2

/-- For [the supplied quantities and conditions](hyp:j), the [channel density](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:Q), these specify the stated inputs. -/
def channelDensity (Q : Kernel (Fin 4) Z) (j : Fin 4) : Z → ℝ :=
  fun z => (Q j |>.rnDeriv (dominatingMeasure Q) z).toReal

/-- For the supplied quantities and conditions, the clip interior is the mathematical object specified below. [The clip Interior](goal) is determined by [the displayed parameters](hyp:δ,x). -/
def clipInterior (δ x : ℝ) : ℝ :=
  max δ (min (1 - δ) x)

/-- For the supplied quantities and conditions, the comparator noise law is the mathematical object specified below. [The comparator Noise Law](goal) is determined by [the displayed parameters](hyp:p,ε). -/
def comparatorNoiseLaw (p ε : ℝ) : Measure ℝ :=
  Causalean.Stat.Privacy.laplaceMeasure (sensitivity p / ε)

/-- the [contrast in range](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:I), these specify the stated inputs. -/
def contrastInRange (I : Matrix (Fin 2) (Fin 2) ℝ) : Prop :=
  ∃ v : TrialParameter, I.mulVec v = contrastVector

/-- the [dominating measure](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:Q), these specify the stated inputs. -/
def dominatingMeasure (Q : Kernel (Fin 4) Z) : Measure Z :=
  ∑ j : Fin 4, Q j

/-- For the supplied quantities and conditions, the dual ray is the mathematical object specified below. [The dual Ray](goal) is determined by [the displayed parameters](hyp:ε,η,s). -/
def dualRay (ε : ℝ) (η : Fin 4 → ℝ) (s : Fin 14) : ℝ :=
  ∑ j : Fin 4, patternRay ε s j * η j

/-- the feasible set is the mathematical object specified below. [The feasible Set](goal) is determined by [the displayed parameters](hyp:ε). -/
def feasibleSet (ε : ℝ) : Set StaircaseWeight :=
  {α | staircaseFeasible ε α}

