/-- For [the supplied quantities and conditions](hyp:p), the [input law](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:θ), these specify the stated inputs. -/
def inputLaw (θ : TrialParameter) (p : ℝ) : Measure PrivateAlphabet :=
  Measure.count.withDensity (fun j => ENNReal.ofReal (piTheta θ p j))

/-- A finite bound for the complete-data path scores. For the displayed inputs and conditions, the stated result follows. [The input Path Score Bound](goal) is determined by [the displayed parameters](hyp:θ,v,p). -/
def inputPathScoreBound {n : ℕ} (θ v : TrialParameter) (p : ℝ) : ℝ :=
  ∑ x : Fin n → Fin 4, |inputPathDirectionalScore θ v p x|

/-- For the supplied quantities and conditions, the local alternative is the mathematical object specified below. [The local Alternative](goal) is determined by [the displayed parameters](hyp:θ0,h,n). -/
def localAlternative (θ0 h : TrialParameter) (n : ℕ) : TrialParameter :=
  fun k => θ0 k + h k / Real.sqrt n

/-- For the supplied quantities and conditions, the local index set is the mathematical object specified below. [The local Index Set](goal) is determined by [the displayed parameters](hyp:θ0,n,H). -/
def localIndexSet (θ0 : TrialParameter) (n : ℕ) (H : ℝ) :
    Set TrialParameter :=
  {h | Real.sqrt ((h 0) ^ 2 + (h 1) ^ 2) ≤ H ∧
       InteriorMeans (localAlternative θ0 h n)}

/-- [the measurable transcript component real density assertion](goal) holds. For [the displayed quantities and conditions](hyp:P,n,x), these specify the stated inputs. -/
lemma measurable_transcriptComponentRealDensity {Z : OutputFamily}
    [∀ n i, MeasurableSpace (Z n i)] {ε : ℝ}
    (P : ProcedureSequence Z ε) (n : ℕ) (x : Fin n → Fin 4) :
    Measurable (transcriptComponentRealDensity P n x) := by
  exact (Measure.measurable_rnDeriv _ _).ennreal_toReal

/-- For [the supplied quantities and conditions](hyp:p,x), the [oa combined value](goal) is the mathematical object specified below. -/
def oaCombinedValue (p : ℝ) (x : PrivateAlphabet × ℝ) : ℝ :=
  oaTrialValue p x.1 + x.2

/-- Parameterize the observed release kernels along a local affine path. The stated result follows. For the displayed quantities and conditions, these specify the stated inputs. [The observed Kernel Family](goal) is determined by [the displayed parameters](hyp:P,θ,v,p,n,u). -/
def observedKernelFamily {Z : OutputFamily}
    [∀ n i, MeasurableSpace (Z n i)] {ε : ℝ}
    (P : ProcedureSequence Z ε) (θ v : TrialParameter) (p : ℝ)
    (n : ℕ) (u : ℝ) : KernelFamily Unit (Z n) := fun i =>
  observedStageKernel P (parameterPath θ v u) p n i

/-- For the supplied quantities and conditions, the output law is the mathematical object specified below. For the displayed quantities and conditions, these specify the stated inputs. [The output Law](goal) is determined by [the displayed parameters](hyp:θ,p,Q). -/
def outputLaw (θ : TrialParameter) (p : ℝ) (Q : Kernel (Fin 4) Z) : Measure Z :=
  ∑ j : Fin 4, ENNReal.ofReal (piTheta θ p j) • Q j

/-- For [the supplied quantities and conditions](hyp:p,s), the [output score](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:θ,ε), these specify the stated inputs. -/
def outputScore (θ : TrialParameter) (p ε : ℝ) (s : Fin 14) : TrialParameter :=
  fun k => patternGradient p ε s k / patternMass θ p ε s

/-- For the supplied quantities and conditions, the parameter path is the mathematical object specified below. [The parameter Path](goal) is determined by [the displayed parameters](hyp:θ,v,u). -/
def parameterPath (θ v : TrialParameter) (u : ℝ) : TrialParameter :=
  fun k ↦ θ k + u * v k

/-- For [the supplied quantities and conditions](hyp:s,j), the [pattern contains](goal) is the mathematical object specified below. -/
def patternContains (s : Fin 14) (j : Fin 4) : Bool :=
  Nat.testBit (s.val + 1) j.val

/-- For [the supplied quantities and conditions](hyp:p,s,t), the [pattern information](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:θ,ε), these specify the stated inputs. -/
def patternInformation (θ : TrialParameter) (p ε : ℝ) (s : Fin 14) (t : ℝ) : ℝ :=
  (projectedGradient p ε s t) ^ 2 / patternMass θ p ε s

/-- For [the supplied quantities and conditions](hyp:p,s), the [pattern mass](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:θ,ε), these specify the stated inputs. -/
def patternMass (θ : TrialParameter) (p ε : ℝ) (s : Fin 14) : ℝ :=
  ∑ j : Fin 4, piTheta θ p j * patternRay ε s j

/-- For [the supplied quantities and conditions](hyp:s,j), the [pattern ray](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:ε), these specify the stated inputs. -/
def patternRay (ε : ℝ) (s : Fin 14) (j : Fin 4) : ℝ :=
  1 + privacyIncrement ε * if patternContains s j then 1 else 0

/-- For [the supplied quantities and conditions](hyp:k,a), the [pilot cell indicator](goal) is the mathematical object specified below. -/
def pilotCellIndicator (k a : Fin 4) : ℝ :=
  if a = k then 1 else 0

/-- For the supplied quantities and conditions, the pilot history theta is the mathematical object specified below. For the displayed quantities and conditions, these specify the stated inputs. [The pilot History Theta](goal) is determined by [the displayed parameters](hyp:p,ε,m,i,h). -/
def pilotHistoryTheta (p ε : ℝ) (m : ℕ → ℕ) {n : ℕ}
    (i : Fin n) (h : PrivateHistory (Z := pilotOutputFamily n) i) :
    TrialParameter :=
  let δ := (m n + 2 : ℝ)⁻¹
  let invFreq (k : Fin 4) :=
    ((Real.exp ε + 3) * pilotHistoryFrequency m i h k - 1) /
      (Real.exp ε - 1)
  fun a =>
    if a = 0 then clipInterior δ (invFreq 1 / controlProb p)
    else clipInterior δ (invFreq 3 / p)

/-- The affine inverse applied to one released-category frequency. For the displayed inputs and conditions, the stated result follows. [The pilot Inverse Frequency](goal) is determined by [the displayed parameters](hyp:ε,x). -/
def pilotInverseFrequency (ε x : ℝ) : ℝ :=
  ((Real.exp ε + 3) * x - 1) / (Real.exp ε - 1)

/-- For the supplied quantities and conditions, the pilot objective zero upper is the mathematical object specified below. [The pilot Objective Zero Upper](goal) is determined by [the displayed parameters](hyp:p,ε). -/
def pilotObjectiveZeroUpper (p ε : ℝ) : ℝ :=
  ∑ s : Fin 14, projectedGradient p ε s 0 ^ 2

/-- For the supplied quantities and conditions, the pilot phi upper is the mathematical object specified below. [The pilot Phi Upper](goal) is determined by [the displayed parameters](hyp:p,ε). -/
def pilotPhiUpper (p ε : ℝ) : ℝ :=
  pilotGradientUpper p ε * (pilotTUpper p ε + 1) / pilotJLower p ε

/-- For [the supplied quantities and conditions](hyp:u), the [pilot prefix embed](goal) is the mathematical object specified below. -/
def pilotPrefixEmbed {ℓ : ℕ} (u : Fin ℓ → Fin 4) : Fin ℓ → PilotOutput :=
  fun j => Sum.inl (u j)

/-- For [the supplied quantities and conditions](hyp:u,k), the [pilot prefix frequency](goal) is the mathematical object specified below. -/
def pilotPrefixFrequency {ℓ : ℕ} (u : Fin ℓ → Fin 4) (k : Fin 4) : ℝ :=
  (ℓ : ℝ)⁻¹ * ∑ j : Fin ℓ, if u j = k then (1 : ℝ) else 0

/-- For the supplied quantities and conditions, the pilot score growth upper is the mathematical object specified below. [The pilot Score Growth Upper](goal) is determined by [the displayed parameters](hyp:p,ε). -/
def pilotScoreGrowthUpper (p ε : ℝ) : ℝ :=
  (1 + pilotTUpper p ε) / pilotJLower p ε

/-- For the supplied quantities and conditions, the pilot t upper is the mathematical object specified below. [The pilot TUpper](goal) is determined by [the displayed parameters](hyp:p,ε). -/
def pilotTUpper (p ε : ℝ) : ℝ :=
  Real.sqrt (pilotObjectiveZeroUpper p ε / pilotLowerA p ε)

/-- For the supplied quantities and conditions, the pilot theta is the mathematical object specified below. For the displayed quantities and conditions, these specify the stated inputs. [The pilot Theta](goal) is determined by [the displayed parameters](hyp:p,ε,m,z). -/
def pilotTheta (p ε : ℝ) (m : ℕ → ℕ) {n : ℕ}
    (z : Transcript (pilotOutputFamily n)) : TrialParameter :=
  let δ := (m n + 2 : ℝ)⁻¹
  let invFreq (k : Fin 4) :=
    ((Real.exp ε + 3) * pilotFrequency m z k - 1) /
      (Real.exp ε - 1)
  fun a =>
    if a = 0 then clipInterior δ (invFreq 1 / controlProb p)
    else clipInterior δ (invFreq 3 / p)

