/-- For [the supplied quantities and conditions](hyp:p,s,t), the [projected gradient](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:ε), these specify the stated inputs. -/
def projectedGradient (p ε : ℝ) (s : Fin 14) (t : ℝ) : ℝ :=
  ∑ k : Fin 2, patternGradient p ε s k * direction t k

/-- For [the supplied quantities and conditions](hyp:p,s,t), the [projected score](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:θ,ε), these specify the stated inputs. -/
def projectedScore (θ : TrialParameter) (p ε : ℝ) (s : Fin 14) (t : ℝ) : ℝ :=
  projectedGradient p ε s t / patternMass θ p ε s

/-- The linear coefficient of the canonical three-mask stationarity equation. For the displayed inputs and conditions, the stated result follows. [The r3 Stationarity Coeff](goal) is determined by [the displayed parameters](hyp:p,μ0,μ1,ε). -/
def r3StationarityCoeff (p μ0 μ1 ε : ℝ) : ℝ :=
  r3Stationarity p μ0 μ1 ε 1 - r3Stationarity p μ0 μ1 ε 0

/-- The canonical weights on masks 0, 5, and 7. The stated result follows. [The r3 Weight](goal) is determined by [the displayed parameters](hyp:ε). -/
def r3Weight (ε : ℝ) : StaircaseWeight :=
  fun s => if s ∈ ({0, 5, 7} : Finset (Fin 14)) then (Real.exp ε + 2)⁻¹ else 0

/-- [A right inverse for the five-output dual matrix](goal) is determined by [the displayed parameters](hyp:ε). -/
noncomputable def r5DualRightInverse (ε : ℝ) : Matrix (Fin 4) (Fin 4) ℝ :=
  let r := Real.exp ε
  let a := (r - 1) * (r + 2)
  !![(r + 1) / a, (r + 1) / a, -1 / (r - 1), -1 / a;
     0, -1 / (r - 1), 1 / (r - 1), 0;
     -1 / a, (r + 1) / a, 0, -1 / a;
     -1 / a, -1 / a, 0, (r + 1) / a]

/-- For [the supplied quantities and conditions](hyp:v), the [reflect treatment parameter](goal) is the mathematical object specified below. -/
def reflectTreatmentParameter (v : TrialParameter) : TrialParameter :=
  fun k => -v (swapTreatmentParameter k)

/-- For [the supplied quantities and conditions](hyp:x), the [region theta](goal) is the mathematical object specified below. -/
def regionTheta (x : RegionParameter) : TrialParameter :=
  fun k => if k = 0 then x.2.1 else x.2.2.1

/-- For the supplied quantities and conditions, the rr pilot probability is the mathematical object specified below. [The rr Pilot Probability](goal) is determined by [the displayed parameters](hyp:ε,j,k). -/
def rrPilotProbability (ε : ℝ) (j k : Fin 4) : ℝ :=
  (if j = k then Real.exp ε else 1) / (Real.exp ε + 3)

/-- Scalar multiplication of a trial-parameter direction. For [the displayed inputs and conditions](hyp:a,v), [the stated result](goal) follows. -/
def scaledDirection (a : ℝ) (v : TrialParameter) : TrialParameter :=
  fun k => a * v k

/-- For [the supplied quantities and conditions](hyp:p), the [sensitivity](goal) is the mathematical object specified below. -/
def sensitivity (p : ℝ) : ℝ :=
  p⁻¹ + (controlProb p)⁻¹

/-- the [staircase feasible](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:ε,α), these specify the stated inputs. -/
def staircaseFeasible (ε : ℝ) (α : StaircaseWeight) : Prop :=
  (∀ s, 0 ≤ α s) ∧ ∀ j, staircaseMatrix ε α j = 1

/-- For [the supplied quantities and conditions](hyp:j), the [staircase matrix](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:ε,α), these specify the stated inputs. -/
def staircaseMatrix (ε : ℝ) (α : StaircaseWeight) (j : Fin 4) : ℝ :=
  ∑ s : Fin 14, α s * patternRay ε s j

/-- the [staircase pattern space](goal) is the mathematical object specified below. -/
def staircasePatternSpace : Finset StaircaseSubset :=
  (Finset.univ : Finset PrivateAlphabet).powerset

/-- the staircase support is the mathematical object specified below. [The staircase Support](goal) is determined by [the displayed parameters](hyp:α). -/
def staircaseSupport (α : StaircaseWeight) : Finset (Fin 14) :=
  Finset.univ.filter (fun s => α s ≠ 0)

/-- For [the supplied quantities and conditions](hyp:x), the [standard normal cdf](goal) is the mathematical object specified below. -/
def standardNormalCDF (x : ℝ) : ℝ :=
  (gaussianMeasure 0 1 (Set.Iic x)).toReal

/-- the [swap treatment channel](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:Q), these specify the stated inputs. -/
def swapTreatmentChannel (Q : Kernel (Fin 4) Z) : Kernel (Fin 4) Z :=
  Q.comap swapTreatmentInput (measurable_of_finite _)

/-- Transpose the two-by-two treatment/outcome membership table of a staircase ray. For [the displayed inputs and conditions](hyp:s), [the stated result](goal) follows. -/
def swapTreatmentPattern (s : Fin 14) : Fin 14 :=
  Fin.ofNat 14 (((s.val + 1) % 4 * 4 + (s.val + 1) / 4) - 1)

/-- the swap treatment weight is the mathematical object specified below. [The swap Treatment Weight](goal) is determined by [the displayed parameters](hyp:α). -/
def swapTreatmentWeight (α : StaircaseWeight) : StaircaseWeight :=
  fun s => α (swapTreatmentPattern s)

/-- the [swapped support](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:K), these specify the stated inputs. -/
def swappedSupport (K : Finset (Fin 14)) : Finset (Fin 14) :=
  K.image swapTreatmentPattern

/-- [The real-valued density of one transcript component](goal) is determined by [the displayed parameters](hyp:P,n,x,z). -/
noncomputable def transcriptComponentRealDensity {Z : OutputFamily}
    [∀ n i, MeasurableSpace (Z n i)] {ε : ℝ}
    (P : ProcedureSequence Z ε) (n : ℕ) (x : Fin n → Fin 4)
    (z : Transcript (Z n)) : ℝ :=
  ((P.transcript n x).rnDeriv (transcriptReferenceMeasure P n) z).toReal

/-- The Radon--Nikodym density of a transcript law against its common finite reference measure. The stated result follows. For the displayed quantities and conditions, these specify the stated inputs. [The transcript Density](goal) is determined by [the displayed parameters](hyp:P,θ,p,n). -/
def transcriptDensity {Z : OutputFamily}
    [∀ n i, MeasurableSpace (Z n i)] {ε : ℝ}
    (P : ProcedureSequence Z ε) (θ : TrialParameter) (p : ℝ) (n : ℕ) :
    Transcript (Z n) → ℝ≥0∞ :=
  (transcriptLaw P θ p n).rnDeriv (transcriptReferenceMeasure P n)

/-- the transcript prefix law is the mathematical object specified below. For the displayed quantities and conditions, these specify the stated inputs. [The transcript Prefix Law](goal) is determined by [the displayed parameters](hyp:P,θ,p,n,k,hk). -/
def transcriptPrefixLaw {Z : OutputFamily}
    [∀ n i, MeasurableSpace (Z n i)] {ε : ℝ}
    (P : ProcedureSequence Z ε) (θ : TrialParameter) (p : ℝ)
    (n k : ℕ) (hk : k ≤ n) : Measure (History (Z n) k hk) :=
  (transcriptLaw P θ p n).map (transcriptPrefix hk)

/-- the [transcript prefix reference measure](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:P,n,k,hk), these specify the stated inputs. -/
def transcriptPrefixReferenceMeasure {Z : OutputFamily}
    [∀ n i, MeasurableSpace (Z n i)] {ε : ℝ}
    (P : ProcedureSequence Z ε) (n k : ℕ) (hk : k ≤ n) :
    Measure (History (Z n) k hk) :=
  (transcriptReferenceMeasure P n).map (transcriptPrefix hk)

/-- The sum of all deterministic-input transcript laws is a common reference
measure for the fixed procedure and sample size. [The stated result](goal) follows. For [the displayed quantities and conditions](hyp:P,n), these specify the stated inputs. -/
def transcriptReferenceMeasure {Z : OutputFamily}
    [∀ n i, MeasurableSpace (Z n i)] {ε : ℝ}
    (P : ProcedureSequence Z ε) (n : ℕ) : Measure (Transcript (Z n)) :=
  ∑ x : Fin n → Fin 4, P.transcript n x

