/-- For the supplied quantities and conditions, the upper envelope is the mathematical object specified below. [The upper Envelope](goal) is determined by [the displayed parameters](hyp:θ,p,ε,t). -/
def upperEnvelope (θ : TrialParameter) (p ε t : ℝ) : ℝ :=
  sSup {u : ℝ | ∃ α ∈ feasibleSet ε, u = informationObjective θ p ε α t}

/-- For the supplied quantities and conditions, the vertex envelope is the mathematical object specified below. [The vertex Envelope](goal) is determined by [the displayed parameters](hyp:θ,p,ε,t). -/
def vertexEnvelope (θ : TrialParameter) (p ε t : ℝ) : ℝ :=
  sSup {u : ℝ | ∃ α ∈ (feasibleSet ε).extremePoints ℝ,
    u = informationObjective θ p ε α t}

/-- For the supplied quantities and conditions, the vt target is the mathematical object specified below. [The vt Target](goal) is determined by [the displayed parameters](hyp:θ,v,a,_x). -/
def vtTarget {X : Type*} (θ v : TrialParameter) (a : ℝ) (_x : X) : ℝ :=
  contrast θ + a * contrast v

/-- For [the supplied quantities and conditions](hyp:v,_a,_x), the [vt target deriv](goal) is the mathematical object specified below. -/
def vtTargetDeriv {X : Type*} (v : TrialParameter) (_a : ℝ) (_x : X) : ℝ :=
  contrast v

/-- the wald critical value is the mathematical object specified below. [The wald Critical Value](goal) is determined by [the displayed parameters](hyp:γ). -/
def waldCriticalValue (γ : ℝ) : ℝ :=
  sInf {z : ℝ | 1 - γ / 2 ≤ standardNormalCDF z}
